const p = $input.first().json;
const prompt = `Tu es expert TikTok affiliate. Crée un script de 25s pour ce produit.
Titre: ${p.title}
Prix: ${p.price}€
Catégorie: ${p.category}
Pourquoi viral: ${p.why_viral}
Hook suggéré: ${p.hook}

Retourne UNIQUEMENT ce JSON valide:
{"script": {"title": "...", "hook": "...0-3s", "scene1": "...3-10s", "scene2": "...10-18s", "scene3": "...18-23s", "cta": "...23-25s", "hashtags": ["#tiktok","#affiliate","#viral","#deal","#pourtoi"], "duration_seconds": 25}}`;

return [{
  json: {
    ...p,
    geminiBody: JSON.stringify({
      contents: [{ parts: [{ text: prompt }] }],
      generationConfig: { temperature: 0.7, maxOutputTokens: 600 }
    })
  }
}];

const geminiResponse = $input.first().json;
const productData = $('Trigger from WF01').item.json;

let script = {};
try {
  const text = geminiResponse.candidates[0].content.parts[0].text;
  const jsonMatch = text.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    const parsed = JSON.parse(jsonMatch[0]);
    script = parsed.script || {};
  }
} catch(e) {
  console.log('Script parse error:', e.message);
  script = {
    title: 'Découvrez ' + (productData.title || 'ce produit'),
    hook: 'Vous ne croirez pas ce que ce produit peut faire...',
    scene1: 'Montrer le produit dans son emballage',
    scene2: 'Démonstration en conditions réelles',
    scene3: 'Avant / Après ou résultat visible',
    cta: 'Lien sb bio pour commander !',
    hashtags: ['#tiktokshop', '#affiliate', '#deal', '#viral', '#pourtoi'],
    duration_seconds: 25
  };
}

return [{
  json: {
    product_id: productData.id || null,
    product_title: productData.title,
    platform: productData.platform,
    script_title: script.title,
    script_hook: script.hook,
    script_scene1: script.scene1,
    script_scene2: script.scene2,
    script_scene3: script.scene3,
    script_cta: script.cta,
    hashtags: (script.hashtags || []).join(' '),
    duration_seconds: script.duration_seconds || 25,
    full_script: JSON.stringify(script),
    generated_at: new Date().toISOString()
  }
}];
